import {readSourceZip} from './source-archive.js';
import {convertCartographer} from './cartographer-import.js';
import {makeCartographerAtlas} from './cartographer-art.js';
export function cartographerDialog(api){
 const {modal,esc,error}=api;
 modal('Import Cartographer region',`<p>Convert Cartographer’s generated RPG Maker maps into editable GBA maps. Layouts and tile positions are kept. Artwork becomes 16-pixel tiles, with separate ground and overhead planes.</p><p>Choose a ZIP containing <b>YAML/MapXXX.yaml</b>, <b>Data/Tilesets.rxdata</b> (or unpacked Tilesets.yaml), and the matching <b>Graphics/Tilesets</b> and <b>Graphics/Autotiles</b> PNG files. Include <b>CartographerOutput</b> for names and continuous connections. Select the generated project, not Cartographer’s application ZIP.</p><label>Generated project ZIP<input type="file" id="cartographerZip" accept=".zip,application/zip"></label><label>Surf terrain tag IDs<input id="cartographerWater" value="5,6,7" inputmode="numeric"></label><label>Grass terrain tag IDs<input id="cartographerGrass" value="2,10,14" inputmode="numeric"></label><p class="small">These are conventional Essentials terrain tags. Adjust them if your source project uses custom tags. Unmatched directional passage cells are blocked for review. Ruby scripts and gameplay data are reported separately.</p><button type="button" id="cartographerRead" class="primary">Convert & review</button><p id="cartographerProgress" role="status"></p>`);
 document.querySelector('#cartographerRead').onclick=async()=>{const button=document.querySelector('#cartographerRead');button.disabled=true;try{const input=document.querySelector('#cartographerZip').files[0];if(!input)throw Error('Choose the generated project ZIP first.');if(input.size>256*1024*1024)throw Error('Keep the project ZIP below 256 MB.');const terrainRules={};for(const[id,kind]of[['cartographerWater','water'],['cartographerGrass','grass']])for(const n of document.querySelector('#'+id).value.split(',').map(s=>s.trim()).filter(Boolean)){if(!/^\d+$/.test(n)||+n>65535)throw Error('Enter comma-separated terrain tag numbers.');if(terrainRules[n])throw Error('A terrain tag cannot be both water and grass.');terrainRules[n]=kind;}
 const target=api.project(),sourceSession=api.session();const progress=s=>{const node=document.querySelector('#cartographerProgress');if(node)node.textContent=s;},entries=await readSourceZip(new Uint8Array(await input.arrayBuffer()),{progress}),session=sourceSession,result=await convertCartographer(entries,{project:target,reader:session?.reader,sourceId:session?.id,makeAtlas:makeCartographerAtlas,terrainRules,progress});
 if(!button.isConnected||api.project()!==target)return;
 modal('Cartographer import review',`<p><b>${result.sources} source maps → ${result.maps.length} GBA maps</b><br>${result.links.length} connections and doors · ${result.assets.length} converted tilesets</p><p>Large maps split into connected sections within the GBA map-buffer limit. Your existing maps stay in the project. This import can be undone.</p>${result.warnings.length?'<h3>Needs review</h3><ul>'+result.warnings.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ul>':'<p>Tile and connection conversion passed.</p>'}<button type="button" id="cartographerReport">Save conversion report</button><p>GBA palette and graphics limits are checked by <b>Export → Edited GBA ROM → Compile & review</b>. This step imports the editable maps; it does not claim all Essentials events are GBA-compatible.</p>`,()=>{if(api.project()!==target)throw Error('The project changed. Convert the region again before importing.');api.change(()=>{api.project().maps.push(...result.maps);api.project().assets.push(...result.assets);api.project().links.push(...result.links);});api.openMap(result.maps[0].id);api.refresh();api.toast('Cartographer maps imported. Check collisions and the conversion notes before export.');},'Import maps');
 document.querySelector('#cartographerReport').onclick=()=>api.saveFile(new Blob([JSON.stringify({maps:result.maps.map(m=>({name:m.name,source:m.cartographer})),warnings:result.warnings,references:result.references},null,2)],{type:'application/json'}),'Cartographer_conversion_report.json').catch(error);
 }catch(e){error(e);}finally{if(button.isConnected)button.disabled=false;}};
}
